// Verify February arithmetic
const inv = [650,2400,2400,1800,900,2400,450,650,1800,1800,2400,1800,450,900,450,450,1200,900,2400,650,900,450,450,1800];
const mInv = inv.reduce((a,b)=>a+b,0);
const receipts = [650,2400,2400,1800,900,2400,450,650,1800,1800,2400,1800,450,900,450,450,1200,900,2400,650,900,450,450,1800,36000];
const rcpt = receipts.reduce((a,b)=>a+b,0);
const bills = 10040+7200+240+1460+3300;
const bankDebits = bills + 48200 + 11280;
const bankCredits = rcpt;
// bank statement check
const beg=384900, end=369630;
console.log('monthly invoices sum', mInv, '(expect 30450); count', inv.length);
console.log('receipts sum', rcpt, 'count', receipts.length, '=> bank credits', bankCredits);
console.log('bank debits', bankDebits, 'beg-debits+credits', beg-bankDebits+bankCredits, 'statement end', end, 'match', beg-bankDebits+bankCredits===end);
// payroll identity
console.log('withholding', 54404-48200, '+ employer 5076 =', (54404-48200)+5076, 'vs remitted 11280');
// February P&L
const rev = 30450 + 8200 + 2000 + 3000;
const exp = 54404+5076+3300+7200+10040+1460+1777.78+240;
console.log('Feb revenue', rev, 'Feb expenses', exp.toFixed(2), 'net', (rev-exp).toFixed(2));
// cash bridge
console.log('cash change', end-beg, 'loss', (rev-exp).toFixed(2), 'diff', (end-beg-(rev-exp)).toFixed(2), '= 1777.78 + 36000-3000-8200-2000 =', (1777.78+36000-3000-8200-2000).toFixed(2));
// TB
const tb = { '1000':369630, '1100':38200, '1300':9600, '1500':64000, '3900':205953,
  '5000':54404+54404, '5010':5076+5076, '5100':3250+3300, '5200':7200+7200, '5300':9920+10040, '5400':1460+1460, '5700':1777.78*2, '5900':240+240 };
const tbc = { '1510':21333+1777.78*2, '2000':17420, '2100':0, '2200':54800+36000-13200, '3000':650000, '4000':40650+43450 };
const D = Object.values(tb).reduce((a,b)=>a+b,0), C = Object.values(tbc).reduce((a,b)=>a+b,0);
console.log('TB Dr', D.toFixed(2), 'Cr', C.toFixed(2), 'balanced', Math.abs(D-C)<1e-9);
console.log('2200 check:', 54800+36000-13200, '= 32800-8200 + 22000-2000 + 36000-3000 =', (32800-8200)+(22000-2000)+(36000-3000));
console.log('1510', 21333+1777.78*2, '4000', 40650+43450);

