const fs = require('fs');
const m1 = JSON.parse(fs.readFileSync('/work/deliverable/month_01/trial_balance.json','utf8'));
const m2 = JSON.parse(fs.readFileSync('/work/deliverable/month_02/trial_balance.json','utf8'));
const jes = JSON.parse(fs.readFileSync('/work/deliverable/month_02/journal_entries.json','utf8'));
const rf = JSON.parse(fs.readFileSync('/work/deliverable/month_02/deferred_revenue_rollforward.json','utf8'));
const f = x => Math.round(parseFloat(x)*100)/100;
// 1. each JE balances
for (const j of jes){ const d=j.lines.reduce((a,l)=>a+f(l.debit),0), c=j.lines.reduce((a,l)=>a+f(l.credit),0);
  if(d!==c) throw 'JE unbalanced '+j.ref+' '+d+' vs '+c; }
// 2. opening TB + Feb JEs = closing TB per account
const bal={}; for(const a in m1.accounts){bal[a]=f(m1.accounts[a].debit)-f(m1.accounts[a].credit);}
for(const j of jes) for(const l of j.lines){ bal[l.account]=(bal[l.account]||0)+f(l.debit)-f(l.credit); }
let ok=true;
const all=new Set([...Object.keys(bal),...Object.keys(m2.accounts)]);
for(const a of all){ const exp=f(m2.accounts[a].debit)-f(m2.accounts[a].credit);
  if(f(bal[a]||0)!==exp){ok=false; console.log('MISMATCH',a,bal[a],exp);} }
console.log('TB roll from Jan + Feb JEs consistent:', ok);
// 3. TB totals
const D=Object.values(m2.accounts).reduce((a,x)=>a+f(x.debit),0), C=Object.values(m2.accounts).reduce((a,x)=>a+f(x.credit),0);
console.log('TB Dr',D.toFixed(2),'Cr',C.toFixed(2), D===C?'balanced':'UNBALANCED');
// 4. rollforward internal + ties to 2200
for(const c of rf.contracts){ if(f(c.opening)+f(c.billed)-f(c.recognized)!==f(c.closing)) console.log('RF row bad',c.contract); }
const rfC=rf.contracts.reduce((a,c)=>a+f(c.closing),0);
console.log('RF closing sum',rfC,'vs 2200',f(m2.accounts['2200'].credit), rfC===f(m2.accounts['2200'].credit)?'ties':'MISMATCH');
const rD=rf.contracts.reduce((a,c)=>a+f(c.opening),0), rB=rf.contracts.reduce((a,c)=>a+f(c.billed),0), rR=rf.contracts.reduce((a,c)=>a+f(c.recognized),0);
console.log('RF totals check:', rD,rB,rR,rD+rB-rR, 'vs stated', rf.totals.opening, rf.totals.billed, rf.totals.recognized, rf.totals.closing);
console.log('Feb JE count', jes.length, 'refs', jes.map(j=>j.ref).join(','));

